import type { DerivedProfile, Plan } from '../types.ts'
import { type AllergenId, type MatchKind, matchIngredient } from './allergens.ts'
import { blockedPatterns } from './patterns.ts'
import { substitute } from './substitute.ts'

/**
 * The model proposes, this file decides. No plan reaches a screen without
 * passing through `gate()`. Changing anything here changes what a person with a
 * sesame allergy is served for dinner, so: tests first, and tell the user.
 */
export type Verdict = 'PASS' | 'REJECT' | 'REJECT_MEAL' | 'OFFER_ALTERNATIVE' | 'BLOCK_ACCOUNT'

export type RejectionCode =
  | 'ALLERGEN'
  | 'KCAL_FLOOR'
  | 'DEFICIT_TOO_STEEP'
  | 'LOSS_RATE_TOO_FAST'
  | 'UNDERWEIGHT_CUT'
  | 'MINOR'

export interface GateReason {
  code: RejectionCode
  /** Populated for ALLERGEN only. */
  allergen?: AllergenId
  matchKind?: MatchKind
  term?: string
  mealId?: string
  itemName?: string
  /** Observed vs. permitted, for the numeric floors. */
  actual?: number
  limit?: number
}

export interface Substitution {
  from: string
  to: string
  injury: string
  pattern: string
}

export interface GateResult {
  verdict: Verdict
  /** The plan as it may be shown. Injury substitutions are already applied. */
  plan: Plan
  reasons: GateReason[]
  substitutions: Substitution[]
}

interface IngredientRef {
  mealId: string
  itemName: string
  ingredient: string
}

/** Every ingredient string in the plan, tagged with where it came from. */
export function allIngredients(plan: Plan): IngredientRef[] {
  const out: IngredientRef[] = []
  for (const meal of plan.meals) {
    for (const item of meal.items) {
      const itemName = item.name.ar
      // The dish name is itself an ingredient claim: "كنافة بالفستق" names a nut
      // the ingredient list may well omit.
      out.push({ mealId: meal.id, itemName, ingredient: itemName })
      out.push({ mealId: meal.id, itemName, ingredient: item.name.en })
      for (const ingredient of item.ingredients) {
        out.push({ mealId: meal.id, itemName, ingredient })
      }
    }
  }
  return out
}

export const KCAL_FLOOR: Record<'m' | 'f', number> = { f: 1200, m: 1500 }
export const MAX_DEFICIT_FRACTION = 0.25
export const MAX_WEEKLY_LOSS_FRACTION = 0.01
export const MIN_BMI_FOR_CUT = 18.5
export const MIN_AGE = 18

export function gate(plan: Plan, profile: DerivedProfile): GateResult {
  const reasons: GateReason[] = []
  const substitutions: Substitution[] = []
  const result = (verdict: Verdict, p: Plan = plan): GateResult => ({
    verdict,
    plan: p,
    reasons,
    substitutions,
  })

  // 0 — Under-18 is checked before anything else. The guide's pseudocode puts it
  // last; running it first means a minor can never receive a body-composition
  // plan even transiently, and the account decision is never masked by a
  // lower-severity verdict from an earlier rule.
  if (profile.age < MIN_AGE) {
    reasons.push({ code: 'MINOR', actual: profile.age, limit: MIN_AGE })
    return result('BLOCK_ACCOUNT')
  }

  // 1 — Allergies: highest priority, no exceptions.
  for (const ref of allIngredients(plan)) {
    for (const match of matchIngredient(ref.ingredient, profile.allergies)) {
      reasons.push({
        code: 'ALLERGEN',
        allergen: match.allergen,
        matchKind: match.kind,
        term: match.term,
        mealId: ref.mealId,
        itemName: ref.itemName,
      })
    }
  }
  if (reasons.length > 0) return result('REJECT_MEAL')

  // 2 — Calorie floors. The model cannot go below these.
  const floor = KCAL_FLOOR[profile.sex]
  if (plan.nutrition.kcal < floor) {
    reasons.push({ code: 'KCAL_FLOOR', actual: plan.nutrition.kcal, limit: floor })
  }
  const deficitLimit = MAX_DEFICIT_FRACTION * profile.tdee
  if (plan.nutrition.deficit > deficitLimit) {
    reasons.push({ code: 'DEFICIT_TOO_STEEP', actual: plan.nutrition.deficit, limit: deficitLimit })
  }
  const lossLimit = MAX_WEEKLY_LOSS_FRACTION * profile.weightKg
  if (plan.nutrition.weeklyLossTargetKg > lossLimit) {
    reasons.push({
      code: 'LOSS_RATE_TOO_FAST',
      actual: plan.nutrition.weeklyLossTargetKg,
      limit: lossLimit,
    })
  }
  if (reasons.length > 0) return result('REJECT')

  // 3 — Injuries: exclude whole movement patterns, then fill the gaps.
  const blocked = blockedPatterns(profile.injuries)
  let adjusted = plan
  if (blocked.size > 0) {
    adjusted = {
      ...plan,
      days: plan.days.map((day) => {
        const exercises = substitute(day.exercises, blocked, profile.equipment)
        for (const ex of exercises) {
          if (ex.substitutedFor) {
            substitutions.push({
              from: ex.substitutedFor.id,
              to: ex.id,
              injury: ex.substitutedFor.injury,
              pattern: ex.substitutedFor.pattern,
            })
          }
        }
        return { ...day, exercises }
      }),
    }
  }

  // 4 — Situations that get no cut plan at all.
  if (profile.bmi < MIN_BMI_FOR_CUT && profile.goal === 'cut') {
    reasons.push({ code: 'UNDERWEIGHT_CUT', actual: profile.bmi, limit: MIN_BMI_FOR_CUT })
    return result('OFFER_ALTERNATIVE', adjusted)
  }

  return result('PASS', adjusted)
}
